const CACHE_NAME="apex-cache-v3",urlsToCache=["/","/shorts","/predictions","/learn","/history","/instant-reactions","/clips","/collabs","/live","/navbar.html","/footer.html","/header.html","/header.json","/videos.json","/css/styles.min.css","/js/custom.min.js"];function fetchAndCache(a){return fetch(a).then(b=>{if(200===b.status){const c=b.clone();caches.open(CACHE_NAME).then(b=>b.put(a,c))}return b})}function isFreshContent(a){const b=new URL(a.url);return"navigate"===a.mode||b.origin===self.location.origin&&(b.pathname.endsWith(".html")||b.pathname.endsWith(".json"))}function networkFirst(a){return fetchAndCache(a).catch(()=>caches.match(a).then(b=>b||("navigate"===a.mode?caches.match("/"):void 0)).then(a=>a||Response.error()))}function cacheFirst(a){return caches.match(a).then(b=>{const c=fetchAndCache(a).catch(()=>Response.error());return b||c})}self.addEventListener("install",a=>{self.skipWaiting(),a.waitUntil(caches.open(CACHE_NAME).then(a=>a.addAll(urlsToCache)))}),self.addEventListener("fetch",a=>{"GET"!==a.request.method||a.respondWith(isFreshContent(a.request)?networkFirst(a.request):cacheFirst(a.request))}),self.addEventListener("activate",a=>{a.waitUntil(caches.keys().then(a=>Promise.all(a.map(a=>{if(a!==CACHE_NAME)return caches.delete(a)}))).then(()=>self.clients.claim()))});